/**
 * /resume — HTML wrapper for the resume PDF.
 *
 * LinkedIn (and other unfurlers) cannot build a preview card from a PDF URL, so
 * this route serves a tiny HTML page that carries the Open Graph tags and then
 * sends the visitor straight to the PDF. Two redirect mechanisms are used:
 * a <meta http-equiv="refresh"> for crawlers and no-JS clients, and an inline
 * location.replace() for browsers.
 *
 * The preview image is public/og-resume.png (1200x627), generated by
 * scripts/make-og-resume.mjs from the supplied portrait card.
 */
export const dynamic = "force-static";

const SITE = "https://yalgar.com";
const PDF = "/resume.pdf?v=2026-11-19-3";
const IMAGE = `${SITE}/og-resume.png`;

const TITLE = "Yash Patel — Resume (PDF)";
const DESCRIPTION =
  "One-page resume for Yash Patel: Drexel University B.S. in Computing and Security Technology (2024), Amazon manager (August 2024 – August 2025), founder of Yalgar Consulting LLC. Opens the PDF.";

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>${TITLE}</title>
<meta name="description" content="${DESCRIPTION}" />
<meta name="robots" content="noindex, follow" />
<link rel="canonical" href="${SITE}/resume" />
<meta http-equiv="refresh" content="0; url=${PDF}" />
<meta property="og:type" content="website" />
<meta property="og:site_name" content="Yalgar Consulting LLC" />
<meta property="og:url" content="${SITE}/resume" />
<meta property="og:title" content="${TITLE}" />
<meta property="og:description" content="${DESCRIPTION}" />
<meta property="og:image" content="${IMAGE}" />
<meta property="og:image:secure_url" content="${IMAGE}" />
<meta property="og:image:type" content="image/png" />
<meta property="og:image:width" content="1200" />
<meta property="og:image:height" content="627" />
<meta property="og:image:alt" content="Yash Patel — Resume. Practical security, stronger outcomes." />
<meta name="twitter:card" content="summary_large_image" />
<meta name="twitter:title" content="${TITLE}" />
<meta name="twitter:description" content="${DESCRIPTION}" />
<meta name="twitter:image" content="${IMAGE}" />
<style>
  :root { color-scheme: light; }
  body { margin: 0; min-height: 100vh; display: grid; place-items: center;
    background: #fcf9f8; color: #1c1b1b;
    font-family: Georgia, "Times New Roman", serif; }
  main { max-width: 32rem; padding: 2rem; text-align: center; }
  h1 { margin: 0 0 1rem; font-size: 1.75rem; font-weight: 600; color: #00152d; }
  p { margin: 0 0 1.5rem; font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
    font-size: 1rem; line-height: 1.5; color: #43474e; }
  a { display: inline-flex; min-height: 48px; align-items: center; justify-content: center;
    padding: 0 1.5rem; background: #0b2a4a; color: #ffffff; text-decoration: none;
    font-family: system-ui, -apple-system, "Segoe UI", sans-serif; font-size: 0.875rem;
    font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; }
</style>
</head>
<body>
<main>
  <h1>Yash Patel — Resume</h1>
  <p>The resume is a PDF. If it does not open automatically, use the link below.</p>
  <a href="${PDF}">Open the resume (PDF)</a>
</main>
<script>window.location.replace(${JSON.stringify(PDF)});</script>
</body>
</html>
`;

export function GET() {
  return new Response(html, {
    status: 200,
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "public, max-age=0, must-revalidate",
    },
  });
}
